"""csw -- chip spread-spectrum watermark, DETECTOR ONLY (the embedding engine is not part of this package).

Each keyed sign is held for one chip; chip lengths and phases are drawn from the key per super-block of SUPER ticks
(chip_ids), so the grid is unknown without the key. Detect (blind, key only): average the suspect within each chip,
high-pass the chip-mean sequence, winsorise, T = sum(r_j w_j) / sqrt(sum r_j^2). Under H0 the chip signs are
independent of the data, so T ~ N(0,1) whatever the autocorrelation (docs/FORMAL.md, T1). Optional search over a
constant tick offset, Bonferroni over the offsets tried.
"""
from __future__ import annotations

import numpy as np
import pandas as pd
from ..addressing import AddressSpec, compute_address
from ..prf import domain_id, prf_sign, prf_u64
from ._stats import loo_residual, winsorize, z_to_p


NAME = "csw"


SUPER = 256          # ticks per super-block; each super-block gets its own keyed chip length and phase


def chip_ids(key: bytes, address: np.ndarray, chip: int) -> np.ndarray:
    """KEYED chip grid. A fixed grid (address // chip) is public once the algorithm is known, so an attacker could
    remove exactly the chip-scale fluctuations (high-pass at the known boundaries). Here every super-block of
    SUPER ticks draws its own chip length in [chip, 2*chip) and phase from the key, so without the key the
    boundaries are unknown and the length changes every few hundred samples (no global spectral line to find).
    Returns a unique int64 id per chip."""
    sb = np.floor_divide(address, SUPER)
    u = prf_u64(key, domain_id("csw-grid"), sb)
    L = chip + (u % np.uint64(chip)).astype(np.int64)
    ph = ((u >> np.uint64(16)) % L.astype(np.uint64)).astype(np.int64)
    local = np.floor_divide(address - sb * SUPER + ph, L)
    return sb * 1024 + local


def _chip_residual(x, address, key, chip, offset, k=2, min_fill=0.5):
    """Chip means of the suspect (chips with at least min_fill x the median chip count), high-passed across chips."""
    cid = chip_ids(key, address - offset, chip)            # copy stamped `offset` ticks ahead of the release
    u, inv = np.unique(cid, return_inverse=True)
    cnt = np.bincount(inv)
    m = np.bincount(inv, weights=x) / cnt
    keep = cnt >= max(1.0, min_fill * np.median(cnt))      # relative to the copy's own density (decimated copies)
    u, m = u[keep], m[keep]
    if u.size < 16:
        return None, None
    return u, winsorize(loo_residual(m, k))


def detect(df: pd.DataFrame, key: bytes, addr: AddressSpec, columns: list[str], chip: int = 16,
           max_shift: int = 0, **_):
    if addr.kind == "keys":
        max_shift = 0
    address = compute_address(df, addr)
    S = int(max_shift)
    per, rows = {}, {}
    for c in columns:
        if c not in df.columns:
            per[c] = {"missing": True}
            continue
        x = df[c].to_numpy(dtype=np.float64)
        ok = np.isfinite(x)
        zz = []
        for off in range(-S, S + 1):
            u, r = _chip_residual(x[ok], address[ok], key, chip, off)
            if u is None:
                break
            den = float(np.sqrt(np.sum(r * r)))
            zz.append(float(np.sum(r * prf_sign(key, domain_id("csw:" + c), u)) / den) if den > 0 else 0.0)
        if len(zz) != 2 * S + 1:
            per[c] = {"skipped": True}
            continue
        rows[c] = np.array(zz)
        per[c] = {"n": int(ok.sum())}
    if not rows:
        return {"method": NAME, "columns": per, "z": 0.0, "p": 1.0}
    Z = np.vstack(list(rows.values())).sum(0) / np.sqrt(len(rows))
    j = int(np.argmax(Z)) if S else 0
    for c, zz in rows.items():
        per[c].update({"z": float(zz[j]), "shift": j - S})
    z = float(Z[j])
    out = {"method": NAME, "columns": per, "z": z, "p": min(1.0, z_to_p(z) * (2 * S + 1)), "chip": chip}
    if S:
        out.update({"shift": j - S, "offsets_tested": 2 * S + 1, "z_by_offset": [float(v) for v in Z]})
    return out
